import { basename } from "node:path";

export function getProgramName(argv1) {
  return basename(argv1 ?? "test18.mjs");
}

export function usageLine(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function formatHelp(programName) {
  return `${usageLine(programName)}

options:
  -h, --help  show this help message and exit
  --a A       instance (JSON string)
  --b B       schema (JSON string)
`;
}

export function formatCliError(programName, message) {
  return `${usageLine(programName)}
${programName}: error: ${message}
`;
}

function isHelpToken(token) {
  if (token === "-h" || token === "--help") {
    return true;
  }

  return token.startsWith("--") && token.length > 2 && "--help".startsWith(token);
}

function isNegativeNumberToken(token) {
  return /^-\d+(\.\d+)?([eE][+-]?\d+)?$/.test(token);
}

function startsKnownAssignment(token) {
  return token.startsWith("--a=") || token.startsWith("--b=");
}

export function parseArgs(argv) {
  const values = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (isHelpToken(token)) {
      return { kind: "help" };
    }

    if (token === "--a" || token === "--b") {
      const key = token.slice(2);
      const next = argv[index + 1];

      if (
        next === undefined ||
        (next.startsWith("-") && !isNegativeNumberToken(next))
      ) {
        return {
          kind: "error",
          message: `argument ${token}: expected one argument`,
        };
      }

      values[key] = next;
      index += 1;
      continue;
    }

    if (token.startsWith("--a=")) {
      values.a = token.slice(4);
      continue;
    }

    if (token.startsWith("--b=")) {
      values.b = token.slice(4);
      continue;
    }

    if (token.startsWith("-") && !isNegativeNumberToken(token)) {
      extras.push(token);

      if (
        !startsKnownAssignment(token) &&
        argv[index + 1] !== undefined &&
        !argv[index + 1].startsWith("-")
      ) {
        extras.push(argv[index + 1]);
        index += 1;
      }

      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (!Object.prototype.hasOwnProperty.call(values, "a")) {
    missing.push("--a");
  }

  if (!Object.prototype.hasOwnProperty.call(values, "b")) {
    missing.push("--b");
  }

  if (missing.length > 0) {
    return {
      kind: "error",
      message: `the following arguments are required: ${missing.join(", ")}`,
    };
  }

  if (extras.length > 0) {
    return {
      kind: "error",
      message: `unrecognized arguments: ${extras.join(" ")}`,
    };
  }

  return {
    kind: "ok",
    values: {
      a: values.a,
      b: values.b,
    },
  };
}

class ErrorTreeNode {
  constructor() {
    this.errors = new Map();
    this.children = new Map();
  }

  addError(error) {
    let node = this;

    for (const segment of error.path) {
      if (!node.children.has(segment)) {
        node.children.set(segment, new ErrorTreeNode());
      }

      node = node.children.get(segment);
    }

    const key = error.validator ?? "__unknown__";
    node.errors.set(key, error);
  }

  get total_errors() {
    let total = this.errors.size;

    for (const child of this.children.values()) {
      total += child.total_errors;
    }

    return total;
  }
}

export class ValidationError extends Error {
  constructor(message, options = {}) {
    super(message);
    this.name = "ValidationError";
    this.path = Array.isArray(options.path) ? [...options.path] : [];
    this.schemaPath = Array.isArray(options.schemaPath)
      ? [...options.schemaPath]
