        break;

      case "properties":
      case "patternProperties":
      case "definitions":
        validateSchemaContainer(value, [...schemaPath, keyword]);
        break;

      case "required":
        validateStringArray(value, [...schemaPath, keyword]);
        break;

      case "enum":
        ensure(Array.isArray(value), "expected an array", [...schemaPath, keyword]);
        break;

      case "const":
        break;

      case "items":
        if (Array.isArray(value)) {
          for (let index = 0; index < value.length; index += 1) {
            validateDraft7Schema(value[index], [...schemaPath, keyword, index]);
          }
        } else {
          validateDraft7Schema(value, [...schemaPath, keyword]);
        }
        break;

      case "additionalItems":
      case "additionalProperties":
      case "contains":
      case "propertyNames":
      case "if":
      case "then":
      case "else":
      case "not":
        validateDraft7Schema(value, [...schemaPath, keyword]);
        break;

      case "allOf":
      case "anyOf":
      case "oneOf":
        ensure(Array.isArray(value) && value.length > 0, "expected a non-empty array", [
          ...schemaPath,
          keyword,
        ]);

        for (let index = 0; index < value.length; index += 1) {
          validateDraft7Schema(value[index], [...schemaPath, keyword, index]);
        }
        break;

      case "dependencies":
      case "dependentRequired":
        ensure(isObjectInstance(value), "expected an object", [
          ...schemaPath,
          keyword,
