        for (const [property, dependency] of Object.entries(value)) {
          if (Array.isArray(dependency)) {
            validateStringArray(dependency, [...schemaPath, keyword, property]);
          } else {
            validateDraft7Schema(dependency, [...schemaPath, keyword, property]);
          }
