        break;

      case "minimum":
      case "maximum":
      case "exclusiveMinimum":
      case "exclusiveMaximum":
        ensure(isNumber(value), "expected a number", [...schemaPath, keyword]);
        break;

      case "multipleOf":
        ensure(isNumber(value) && value > 0, "expected a positive number", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "minItems":
      case "maxItems":
      case "minLength":
      case "maxLength":
      case "minProperties":
      case "maxProperties":
        ensure(isNonNegativeInteger(value), "expected a non-negative integer", [
