        break;

      case "pattern":
        ensure(typeof value === "string", "expected a string", [
          ...schemaPath,
          keyword,
        ]);
        break;

      case "uniqueItems":
        ensure(typeof value === "boolean", "expected a boolean", [
          ...schemaPath,
          keyword,
        ]);
        break;

      default:
