      current === null ||
      current === undefined ||
      !Object.prototype.hasOwnProperty.call(current, token)
    ) {
      throw new Error(`Unresolvable JSON Pointer ref: ${ref}`);
    }

    current = current[token];
  }

  return current;
}

    for (const property of Object.keys(instance)) {
      const coveredByProperty = knownProperties.has(property);
      const coveredByPattern = patterns.some(({ regex }) => regex.test(property));

      if (!coveredByProperty && !coveredByPattern) {
        extras.push(property);
      }
    }

    if (extras.length > 0) {
      if (value === false) {
        errors.push(
          createValidationError("additionalProperties validation failed", {
            path: state.instancePath,
            schemaPath: [...state.schemaPath, "additionalProperties"],
            validator: "additionalProperties",
            validatorValue: value,
            instance,
            schema,
          })
        );
      } else if (value !== true) {
        for (const property of extras) {
          errors.push(
            ...validate(
              value,
              instance[property],
              childState(state, property, "additionalProperties")
            )
          );
        }
      }
    }
  }
  break;

case "minProperties":
  if (isObjectInstance(instance) && Object.keys(instance).length < value) {
    errors.push(
      createValidationError("minProperties validation failed", {
        path: state.instancePath,
        schemaPath: [...state.schemaPath, "minProperties"],
        validator: "minProperties",
        validatorValue: value,
        instance,
        schema,
      })
    );
  }
  break;

case "maxProperties":
  if (isObjectInstance(instance) && Object.keys(instance).length > value) {
    errors.push(
      createValidationError("maxProperties validation failed", {
        path: state.instancePath,
        schemaPath: [...state.schemaPath, "maxProperties"],
        validator: "maxProperties",
        validatorValue: value,
        instance,
        schema,
      })
    );
  }
  break;

case "propertyNames":
  if (isObjectInstance(instance)) {
    for (const property of Object.keys(instance)) {
      const suberrors = validate(value, property, {
        ...state,
        schemaPath: [...state.schemaPath, "propertyNames"],
      });

      if (suberrors.length > 0) {
        errors.push(
          createValidationError("propertyNames validation failed", {
            path: state.instancePath,
            schemaPath: [...state.schemaPath, "propertyNames"],
            validator: "propertyNames",
            validatorValue: value,
            instance,
            schema,
            context: suberrors,
          })
        );
      }
    }
  }
  break;

case "items":
  if (Array.isArray(instance)) {
    if (Array.isArray(value)) {
      const sharedLength = Math.min(instance.length, value.length);

      for (let index = 0; index < sharedLength; index += 1) {
        errors.push(
          ...validate(value[index], instance[index], childState(state, index, [
            "items",
            index,
          ]))
        );
      }

      if (instance.length > value.length) {
        if (schema.additionalItems === false) {
          errors.push(
            createValidationError("additionalItems validation failed", {
              path: state.instancePath,
              schemaPath: [...state.schemaPath, "additionalItems"],
              validator: "additionalItems",
              validatorValue: schema.additionalItems,
              instance,
              schema,
            })
          );
        } else if (
          schema.additionalItems !== undefined &&
          schema.additionalItems !== true
        ) {
          for (let index = value.length; index < instance.length; index += 1) {
            errors.push(
              ...validate(
                schema.additionalItems,
                instance[index],
                childState(state, index, "additionalItems")
              )
            );
          }
        }
      }
    } else {
      for (let index = 0; index < instance.length; index += 1) {
        errors.push(
          ...validate(value, instance[index], childState(state, index, "items"))
        );
      }
    }
  }
  break;

case "additionalItems":
  break;

case "minItems":
  if (Array.isArray(instance) && instance.length < value) {
    errors.push(
      createValidationError("minItems validation failed", {
        path: state.instancePath,
        schemaPath: [...state.schemaPath, "minItems"],
        validator: "minItems",
        validatorValue: value,
        instance,
        schema,
      })
    );
  }
  break;

case "maxItems":
  if (Array.isArray(instance) && instance.length > value) {
    errors.push(
      createValidationError("maxItems validation failed", {
        path: state.instancePath,
        schemaPath: [...state.schemaPath, "maxItems"],
        validator: "maxItems",
        validatorValue: value,
        instance,
        schema,
      })
    );
  }
  break;

case "uniqueItems":
  if (value === true && Array.isArray(instance)) {
    let duplicateFound = false;

    for (let left = 0; left < instance.length && !duplicateFound; left += 1) {
      for (let right = left + 1; right < instance.length; right += 1) {
        if (deepEqual(instance[left], instance[right])) {
          duplicateFound = true;
          break;
        }
      }
    }

    if (duplicateFound) {
      errors.push(
        createValidationError("uniqueItems validation failed", {
          path: state.instancePath,
          schemaPath: [...state.schemaPath, "uniqueItems"],
          validator: "uniqueItems",
          validatorValue: value,
          instance,
          schema,
        })
      );
    }
