        break;
      }
    }

    if (!containsMatch) {
      errors.push(
        createValidationError("contains validation failed", {
          path: state.instancePath,
          schemaPath: [...state.schemaPath, "contains"],
          validator: "contains",
          validatorValue: value,
          instance,
          schema,
