case "dependencies":
case "dependentRequired":
  if (isObjectInstance(instance)) {
    for (const [property, dependency] of Object.entries(value)) {
      if (!Object.prototype.hasOwnProperty.call(instance, property)) {
        continue;
      }

      if (Array.isArray(dependency)) {
        for (const requiredProperty of dependency) {
          if (!Object.prototype.hasOwnProperty.call(instance, requiredProperty)) {
            errors.push(
              createValidationError("dependencies validation failed", {
                path: state.instancePath,
                schemaPath: [...state.schemaPath, keyword, property],
                validator: keyword,
                validatorValue: dependency,
                instance,
                schema,
              })
            );
          }
        }
      } else {
        errors.push(
          ...validate(dependency, instance, {
            ...state,
            schemaPath: [...state.schemaPath, keyword, property],
          })
        );
      }
    }
  }
  break;

case "allOf":
  for (let index = 0; index < value.length; index += 1) {
    errors.push(
      ...validate(value[index], instance, {
        ...state,
        schemaPath: [...state.schemaPath, "allOf", index],
      })
    );
  }
  break;

case "anyOf": {
  const collected = [];
  let validBranch = false;

  for (let index = 0; index < value.length; index += 1) {
    const suberrors = validate(value[index], instance, {
      ...state,
      schemaPath: [...state.schemaPath, "anyOf", index],
    });

    if (suberrors.length === 0) {
      validBranch = true;
      break;
    }

    collected.push(...suberrors);
  }

  if (!validBranch) {
    errors.push(
      createValidationError("anyOf validation failed", {
        path: state.instancePath,
        schemaPath: [...state.schemaPath, "anyOf"],
        validator: "anyOf",
        validatorValue: value,
        instance,
        schema,
        context: collected,
      })
    );
  }
  break;
}

case "oneOf": {
  const collected = [];
  let validCount = 0;

  for (let index = 0; index < value.length; index += 1) {
    const suberrors = validate(value[index], instance, {

            ...state,
            schemaPath: [...state.schemaPath, "oneOf", index],
          });

          if (suberrors.length === 0) {
            validCount += 1;
          } else {
            collected.push(...suberrors);
          }
        }

        if (validCount !== 1) {
          errors.push(
            createValidationError("oneOf validation failed", {
              path: state.instancePath,
              schemaPath: [...state.schemaPath, "oneOf"],
              validator: "oneOf",
              validatorValue: value,
              instance,
              schema,
              context: validCount === 0 ? collected : [],
            })
          );
        }
        break;
      }

      case "not":
        if (
          validate(value, instance, {
            ...state,
            schemaPath: [...state.schemaPath, "not"],
          }).length === 0
        ) {
          errors.push(
            createValidationError("not validation failed", {
              path: state.instancePath,
              schemaPath: [...state.schemaPath, "not"],
              validator: "not",
              validatorValue: value,
              instance,
              schema,
            })
          );
        }
        break;

      case "if": {
        const ifErrors = validate(value, instance, {
          ...state,
          schemaPath: [...state.schemaPath, "if"],
        });

        if (ifErrors.length === 0) {
          if (Object.prototype.hasOwnProperty.call(schema, "then")) {
            errors.push(
              ...validate(schema.then, instance, {
                ...state,
                schemaPath: [...state.schemaPath, "then"],
              })
            );
          }
        } else if (Object.prototype.hasOwnProperty.call(schema, "else")) {
          errors.push(
            ...validate(schema.else, instance, {
              ...state,
              schemaPath: [...state.schemaPath, "else"],
            })
          );
        }
        break;
      }

      case "then":
      case "else":
      case "definitions":
      case "$id":
      case "title":
      case "description":
      case "default":
      case "format":
      case "contentMediaType":
      case "contentEncoding":
        break;

      default:
        break;
    }
  }

  return errors;
}

export class Draft7Validator {
  constructor(schema) {
    this.schema = schema;
  }

  *iterErrors(instance) {
    yield* validate(this.schema, instance, {
      rootSchema: this.schema,
      instancePath: [],
      schemaPath: [],
    });
  }

  *iter_errors(instance) {
    yield* this.iterErrors(instance);
  }

  isValid(instance) {
    for (const _error of this.iterErrors(instance)) {
      return false;
    }

    return true;
  }

  is_valid(instance) {
    return this.isValid(instance);
  }

  checkSchema(schema = this.schema) {
    return checkDraft7Schema(schema);
  }

  check_schema(schema = this.schema) {
    return this.checkSchema(schema);
  }

  static checkSchema(schema) {
    return checkDraft7Schema(schema);
  }

  static check_schema(schema) {
    return checkDraft7Schema(schema);
  }
}
